-- ============================================================
-- Role-based assessments, AI recommendation cache, extra skills / questions / courses.
-- Run automatically on startup by RoleAssessmentSchema. Safe to run repeatedly.
-- ============================================================
CREATE TABLE IF NOT EXISTS ed_job_roles (
  role_id     BIGINT AUTO_INCREMENT PRIMARY KEY,
  role_name   VARCHAR(100) NOT NULL UNIQUE,
  description VARCHAR(300)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS ed_job_role_skills (
  role_id    BIGINT NOT NULL,
  skill_id   BIGINT NOT NULL,
  weight_pct INT    NOT NULL,
  PRIMARY KEY (role_id, skill_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS ed_role_attempts (
  role_attempt_id BIGINT AUTO_INCREMENT PRIMARY KEY,
  employee_id     BIGINT NOT NULL,
  role_id         BIGINT NOT NULL,
  overall_pct     DECIMAL(5,2) NOT NULL,
  taken_at        DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_role_attempt_emp (employee_id, taken_at)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS ed_role_attempt_skills (
  role_attempt_id BIGINT NOT NULL,
  skill_id        BIGINT NOT NULL,
  weight_pct      INT NOT NULL,
  marks_earned    DECIMAL(6,2) NOT NULL,
  skill_pct       DECIMAL(5,2) NOT NULL,
  attempt_id      BIGINT NULL,
  PRIMARY KEY (role_attempt_id, skill_id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS ed_ai_recommendations (
  role_attempt_id BIGINT NOT NULL PRIMARY KEY,
  employee_id     BIGINT NOT NULL,
  source          VARCHAR(20) NOT NULL,
  content         MEDIUMTEXT NOT NULL,
  created_at      DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;




